/// <reference types="astro/client" />

/** Worker bindings (`env` of `cloudflare:workers` and of Hono). DB and IMAGENES keep their deployed names. */
declare namespace Cloudflare {
  interface Env {
    DB: D1Database;
    IMAGENES: R2Bucket;
    ASSETS: Fetcher;
  }
}

type Env = Cloudflare.Env;

declare namespace App {
  interface Locals {
    /** Store language: set by the middleware on every page (Spanish if there's no store yet). */
    language?: import("./packages/core/index").Language;
    /** Set by the middleware on /panel pages (it already decided they can be shown). */
    panel?: {
      status: import("./packages/core/index").StoreStatus;
      session: import("./packages/core/index").SessionType | null;
    };
  }
}

/** Generated by integrations/claim-code.mjs on every build: only the code's SHA-256 (hex). */
declare module "virtual:tiendita/claim" {
  export const claimCodeHash: string;
}
